"""C code emitter for FWL.

Walks the analyzed AST and emits valid .bpf.c with auto-generated
bounds checks, byte-order conversions, and protocol parsing.
"""

from fwl.analyzer import AnalyzedFunc, AnalysisResult, PROTO_NUMBERS
from fwl.ast_nodes import (
  Action,
  ActionType,
  AssignStmt,
  BinOp,
  BuiltinCall,
  ChainStmt,
  Cidr,
  Compare,
  CompOp,
  FieldAccess,
  IfStmt,
  InlineC,
  ListLit,
  NameRef,
  NumberLit,
  RuleStmt,
  StringLit,
  UnaryOp,
)

# Template fragments for the generated C.
_FILE_HEADER = """\
/// @file {filename}
/// @brief Generated by FWL compiler.  Do not edit.

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#define ETH_P_IP    0x0800
#define IPPROTO_TCP  6
#define IPPROTO_UDP  17
#define IPPROTO_ICMP 1

struct ethhdr {{
  unsigned char h_dest[6];
  unsigned char h_source[6];
  __be16 h_proto;
}} __attribute__((packed));

struct iphdr {{
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
  __u8 ihl:4, version:4;
#else
  __u8 version:4, ihl:4;
#endif
  __u8 tos;
  __be16 tot_len;
  __be16 id;
  __be16 frag_off;
  __u8 ttl;
  __u8 protocol;
  __sum16 check;
  __be32 saddr;
  __be32 daddr;
}};

struct tcphdr {{
  __be16 source;
  __be16 dest;
  __be32 seq;
  __be32 ack_seq;
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
  __u16 res1:4, doff:4, fin:1, syn:1, rst:1, psh:1,
        ack:1, urg:1, ece:1, cwr:1;
#else
  __u16 doff:4, res1:4, cwr:1, ece:1, urg:1, ack:1,
        psh:1, rst:1, syn:1, fin:1;
#endif
  __be16 window;
  __sum16 check;
  __be16 urg_ptr;
}};

struct udphdr {{
  __be16 source;
  __be16 dest;
  __be16 len;
  __sum16 check;
}};

"""

_COUNTERS_MAP = """\
struct RuleCounter {{
  __u64 packets;
  __u64 bytes;
}};

struct {{
  __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
  __uint(max_entries, {max_entries});
  __type(key, __u32);
  __type(value, struct RuleCounter);
}} counters SEC(".maps");

static __always_inline void bump_counter(
    __u32 idx, __u32 pkt_len) {{
  struct RuleCounter* ctr =
      bpf_map_lookup_elem(&counters, &idx);
  if (ctr) {{
    ctr->packets += 1;
    ctr->bytes += pkt_len;
  }}
}}

"""

_LICENSE = '\nchar _license[] SEC("license") = "GPL";\n'


class Emitter:
  """Emits BPF C code from an analyzed FWL program."""

  def __init__(self, result: AnalysisResult, filename: str = "fwl_out"):
    self._result = result
    self._filename = filename
    self._buf: list[str] = []
    self._indent = 0

  def emit(self) -> str:
    """Generate the complete .bpf.c file.

    Returns:
      Generated C source code as a string.
    """
    self._buf = []
    self._emit_header()
    self._emit_maps()
    for af in self._result.funcs:
      self._emit_func(af)
    self._line(_LICENSE)
    return "".join(self._buf)

  # ---- Output helpers ----

  def _line(self, text: str = ""):
    """Emit a line of code at current indent level."""
    if text:
      self._buf.append("  " * self._indent + text + "\n")
    else:
      self._buf.append("\n")

  def _raw(self, text: str):
    """Emit raw text with no indent or newline."""
    self._buf.append(text)

  def _push(self):
    """Increase indent."""
    self._indent += 1

  def _pop(self):
    """Decrease indent."""
    self._indent -= 1

  # ---- Top-level sections ----

  def _emit_header(self):
    self._raw(_FILE_HEADER.format(filename=self._filename))

  def _emit_maps(self):
    has_counters = any(af.counters for af in self._result.funcs)
    if has_counters:
      max_entries = 1024
      self._raw(_COUNTERS_MAP.format(max_entries=max_entries))

  def _emit_func(self, af: AnalyzedFunc):
    func = af.func
    sec = func.hook
    self._line(f'SEC("{sec}")')
    self._line(f"int {func.name}(struct xdp_md* ctx) {{")
    self._push()

    # Packet data pointers.
    self._line("void* data = (void*)(long)ctx->data;")
    self._line("void* data_end = (void*)(long)ctx->data_end;")
    self._line()

    # L2 parse (always needed).
    self._emit_l2_parse()

    # L3 parse (if any IP field accessed).
    if af.needs_ip:
      self._emit_l3_parse()

    # L4 parse (if any port/TCP/UDP field accessed).
    if af.needs_any_l4:
      self._emit_l4_parse(af)

    # Packet length for counters.
    self._line("__u32 pkt_len = data_end - data;")
    self._line()

    # Function body.
    self._emit_body(af, func.body)

    # Default return.
    if self._result.default_action == ActionType.DROP:
      self._line("return XDP_DROP;")
    else:
      self._line("return XDP_PASS;")

    self._pop()
    self._line("}")
    self._line()

  # ---- Protocol parsing ----

  def _emit_l2_parse(self):
    self._line("// --- L2: Ethernet ---")
    self._line("struct ethhdr* eth = data;")
    self._line("if ((void*)(eth + 1) > data_end)")
    self._push()
    self._line("return XDP_PASS;")
    self._pop()
    self._line(
      "if (eth->h_proto != bpf_htons(ETH_P_IP))")
    self._push()
    self._line("return XDP_PASS;")
    self._pop()
    self._line()

  def _emit_l3_parse(self):
    self._line("// --- L3: IPv4 ---")
    self._line("struct iphdr* ip = (void*)(eth + 1);")
    self._line("if ((void*)(ip + 1) > data_end)")
    self._push()
    self._line("return XDP_PASS;")
    self._pop()
    self._line()

  def _emit_l4_parse(self, af: AnalyzedFunc):
    self._line("// --- L4: TCP / UDP ---")
    self._line("__u16 src_port = 0;")
    self._line("__u16 dst_port = 0;")
    self._line(
      "__u32 l4_off = sizeof(*eth) + (ip->ihl * 4);")
    self._line()

    self._line("if (ip->protocol == IPPROTO_TCP) {")
    self._push()
    self._line("struct tcphdr* tcp = data + l4_off;")
    self._line("if ((void*)(tcp + 1) > data_end)")
    self._push()
    self._line("return XDP_PASS;")
    self._pop()
    self._line("src_port = bpf_ntohs(tcp->source);")
    self._line("dst_port = bpf_ntohs(tcp->dest);")
    self._pop()
    self._line("} else if (ip->protocol == IPPROTO_UDP) {")
    self._push()
    self._line("struct udphdr* udp = data + l4_off;")
    self._line("if ((void*)(udp + 1) > data_end)")
    self._push()
    self._line("return XDP_PASS;")
    self._pop()
    self._line("src_port = bpf_ntohs(udp->source);")
    self._line("dst_port = bpf_ntohs(udp->dest);")
    self._pop()
    self._line("}")
    self._line()

  # ---- Body emission ----

  def _emit_body(self, af: AnalyzedFunc, body: list):
    for stmt in body:
      self._emit_stmt(af, stmt)

  def _emit_stmt(self, af: AnalyzedFunc, stmt):
    """Emit a single statement."""
    if isinstance(stmt, IfStmt):
      self._emit_if(af, stmt)
    elif isinstance(stmt, Action):
      self._emit_action(stmt)
    elif isinstance(stmt, InlineC):
      self._emit_inline_c(stmt)
    elif isinstance(stmt, ChainStmt):
      self._emit_chain(stmt)
    elif isinstance(stmt, BuiltinCall):
      self._emit_builtin_call(af, stmt)
    elif isinstance(stmt, AssignStmt):
      self._emit_assign(stmt)
    elif isinstance(stmt, RuleStmt):
      self._emit_rule_in_func(af, stmt)

  def _emit_if(self, af: AnalyzedFunc, stmt: IfStmt):
    cond = self._expr(stmt.condition)
    # Add source line reference.
    self._line(f"// fwl:{stmt.line}")
    self._line(f"if ({cond}) {{")
    self._push()
    self._emit_body(af, stmt.body)
    self._pop()

    for elif_cond, elif_body in stmt.elifs:
      econd = self._expr(elif_cond)
      self._line(f"}} else if ({econd}) {{")
      self._push()
      self._emit_body(af, elif_body)
      self._pop()

    if stmt.else_body:
      self._line("} else {")
      self._push()
      self._emit_body(af, stmt.else_body)
      self._pop()

    self._line("}")

  def _emit_action(self, stmt: Action):
    if stmt.action == ActionType.DROP:
      self._line("return XDP_DROP;")
    elif stmt.action == ActionType.ALLOW:
      self._line("return XDP_PASS;")
    else:
      self._line("return XDP_PASS;")

  def _emit_inline_c(self, stmt: InlineC):
    self._line(f"// fwl:{stmt.line} — inline C")
    self._line("{")
    self._push()
    for cline in stmt.code.strip().split("\n"):
      self._line(cline.strip())
    self._pop()
    self._line("}")

  def _emit_chain(self, stmt: ChainStmt):
    self._line(f"// fwl:{stmt.line} — chain {stmt.target}")
    self._line(
      "bpf_tail_call(ctx, &prog_array, "
      f"{hash(stmt.target) % 32});")

  def _emit_builtin_call(self, af: AnalyzedFunc, stmt: BuiltinCall):
    if stmt.name == "count":
      name = "unknown"
      if stmt.args and isinstance(stmt.args[0], NameRef):
        name = stmt.args[0].name
      for ci in af.counters:
        if ci.name == name:
          self._line(f"// count: {name}")
          self._line(f"bump_counter({ci.index}, pkt_len);")
          break

  def _emit_assign(self, stmt: AssignStmt):
    val = self._expr(stmt.value)
    self._line(f"__u64 {stmt.name} = {val};")

  def _emit_rule_in_func(self, af: AnalyzedFunc, stmt: RuleStmt):
    """Emit a tier 1 rule embedded in a tier 2 function body."""
    conditions = []
    for m in stmt.matches:
      c = self._match_to_c(m)
      if c:
        conditions.append(c)
    if conditions:
      combined = " && ".join(conditions)
      action = "XDP_DROP" if stmt.action == ActionType.DROP else "XDP_PASS"
      self._line(f"if ({combined})")
      self._push()
      self._line(f"return {action};")
      self._pop()

  def _match_to_c(self, m) -> str:
    """Convert a MatchClause to a C condition string."""
    if m.field == "dst_port":
      vals = " || ".join(
        f"dst_port == {self._expr(v)}" for v in m.values)
      return f"({vals})" if len(m.values) > 1 else vals
    elif m.field == "src_port":
      vals = " || ".join(
        f"src_port == {self._expr(v)}" for v in m.values)
      return f"({vals})" if len(m.values) > 1 else vals
    elif m.field == "proto":
      val = m.values[0]
      if isinstance(val, NameRef):
        num = PROTO_NUMBERS.get(val.name, 0)
        return f"ip->protocol == {num}"
      return f"ip->protocol == {self._expr(val)}"
    elif m.field in ("src_ip", "src_net"):
      return f"ip->saddr == {self._expr(m.values[0])}"
    elif m.field in ("dst_ip", "dst_net"):
      return f"ip->daddr == {self._expr(m.values[0])}"
    return ""

  # ---- Expression emission ----

  def _expr(self, node) -> str:
    """Convert an expression AST node to a C expression string."""
    if isinstance(node, NumberLit):
      return str(node.value)
    elif isinstance(node, StringLit):
      return f'"{node.value}"'
    elif isinstance(node, NameRef):
      # Map well-known names.
      if node.name in PROTO_NUMBERS:
        return str(PROTO_NUMBERS[node.name])
      return node.name
    elif isinstance(node, FieldAccess):
      return self._field_to_c(node)
    elif isinstance(node, Compare):
      left = self._expr(node.left)
      right = self._expr(node.right)
      op = self._comp_op(node.op)
      return f"{left} {op} {right}"
    elif isinstance(node, BinOp):
      left = self._expr(node.left)
      right = self._expr(node.right)
      op = "&&" if node.op == "and" else "||"
      return f"({left} {op} {right})"
    elif isinstance(node, UnaryOp):
      operand = self._expr(node.operand)
      return f"!({operand})"
    elif isinstance(node, BuiltinCall):
      return f"/* {node.name}(...) */"
    elif isinstance(node, Cidr):
      return f"/* CIDR {node.addr}/{node.prefix} */"
    elif isinstance(node, ListLit):
      items = ", ".join(self._expr(i) for i in node.items)
      return f"/* [{items}] */"
    return str(node)

  def _field_to_c(self, fa: FieldAccess) -> str:
    """Map pkt.field to C variable/expression."""
    chain = fa.chain
    if not chain:
      return fa.root

    field = chain[0]
    if field == "dst_port":
      return "dst_port"
    elif field == "src_port":
      return "src_port"
    elif field == "src_ip":
      return "ip->saddr"
    elif field == "dst_ip":
      return "ip->daddr"
    elif field == "proto":
      return "ip->protocol"
    elif field == "ttl":
      return "ip->ttl"
    elif field == "tcp" and len(chain) > 1:
      tcp_field = chain[1]
      return f"tcp->{tcp_field}"
    elif field == "udp" and len(chain) > 1:
      udp_field = chain[1]
      return f"udp->{udp_field}"

    return ".".join(fa.parts)

  def _comp_op(self, op: CompOp) -> str:
    """Convert CompOp enum to C operator string."""
    return {
      CompOp.EQ: "==",
      CompOp.NEQ: "!=",
      CompOp.GT: ">",
      CompOp.LT: "<",
      CompOp.GTE: ">=",
      CompOp.LTE: "<=",
      CompOp.IN: "==",
      CompOp.NOT_IN: "!=",
    }[op]


def emit(result: AnalysisResult, filename: str = "fwl_out") -> str:
  """Generate BPF C source from an analysis result.

  Args:
    result: Output of analyzer.analyze().
    filename: Base name for the generated file.

  Returns:
    Complete .bpf.c source code as a string.
  """
  return Emitter(result, filename).emit()
